import Foundation
import XCTest
import Synchronization
import AgentRuntimeKit
import AgentSessionContracts
import AgentSessionHydration

private struct Index: Sendable, Equatable { let date:Date?;let count:Int }
private struct ProbeState {var events:[String]=[];var ids:[UUID]=[];var states:[AgentSessionRunState]=[];var flags:[Bool]=[];var next:Int?;var observations:[AgentSessionHydrationObservation]=[];var actorWasIsolated=false}
private final class Probe: Sendable {
    let state=Mutex(ProbeState())
    func event(_ value:String){state.withLock{$0.events.append(value)}}
}
private func session(_ transcript:Bool=true)->AgentSession {
    let item=AgentChatItem(id:UUID(uuidString:"00000000-0000-0000-0000-000000000001")!,timestamp:Date(timeIntervalSince1970:10),kind:.user,text:"request",sequenceIndex:5)
    let t=AgentTranscript(turns:[.init(id:item.id,request:.init(from:item),startedAt:item.timestamp)],nextSequenceIndex:6)
    return .init(id:UUID(uuidString:"00000000-0000-0000-0000-000000000002")!,name:"session",items:[AgentChatItemPersist(id:item.id,timestamp:item.timestamp,kind:item.kind,text:item.text,attachments:[],taggedFileAttachments:[],toolName:nil,toolInvocationID:nil,toolArgsJSON:nil,toolResultJSON:nil,toolIsError:nil,toolResultStatus:nil,reasoning:nil,sequenceIndex:item.sequenceIndex,workflow:nil,codexGoalMode:nil,isLocalControlPlaneEcho:false)],transcript:transcript ? t:nil,itemCount:1,lastUserMessageAt:Date(timeIntervalSince1970:10),agentKind:"host",agentModel:"model",lastRunState:"completed",providerSessionID:"external-provider-id")
}
private func ports(_ input:AgentSession?,_ probe:Probe=Probe())->AgentSessionHydrationServices<String,Int,Index> {
    .init(load:{id in probe.event("load");probe.state.withLock{$0.ids.append(id)};return input},select:{s in probe.event("select");return s.agentModel ?? "default"},persistedWorkingItems:{s in probe.event("persisted");return s.items.map{AgentChatItem(id:$0.id,timestamp:$0.timestamp,kind:$0.kind,text:$0.text,sequenceIndex:$0.sequenceIndex)}},containsExcludedRows:{_,flag in probe.event("excluded");probe.state.withLock{$0.flags.append(flag)};return false},rebuild:{t,_,state,flag in probe.event("rebuild");probe.state.withLock{$0.states.append(state);$0.flags.append(flag)};return t},build:{_,state,next,flag in probe.event("build");probe.state.withLock{$0.states.append(state);$0.next=next;$0.flags.append(flag)};return .init(nextSequenceIndex:next)},normalizeFrozenLimits:{t in probe.event("normalize");return t},workingItems:{t in probe.event("working");return t.turns.compactMap{$0.request?.toItem()}},protectedTurnID:{t in probe.event("protection");return t.turns.first?.id},present:{_,_,selection,_ in probe.event("present");return selection.count+100},transcriptRecency:{_ in probe.event("transcriptDate");return Date(timeIntervalSince1970:20)},itemRecency:{_ in probe.event("itemDate");return Date(timeIntervalSince1970:30)},visibleCount:{_ in probe.event("visibleCount");return 99},index:{_,date,count in probe.event("index");return .init(date:date,count:count)},clockMS:{nil},observe:{o in probe.state.withLock{$0.observations.append(o)}})
}
@MainActor
final class HydrationTests:XCTestCase {
    func testMissingSessionReturnsNilWithoutPreparingAnything() async throws {let p=Probe();let result=try await AgentSessionHydrationService(services:ports(nil,p)).prepare(sessionID:UUID(),hasPendingQuestionUI:false);XCTAssertNil(result);XCTAssertEqual(p.state.withLock{$0.events},["load"]);XCTAssertEqual(p.state.withLock{$0.observations.last?.outcome},.missingSession)}
    func testCanonicalSessionUsesOriginalTranscriptWithoutBuildOrRebuild() async throws {let s=session(),p=Probe(),r=try await AgentSessionHydrationService(services:ports(s,p)).prepare(sessionID:s.id,hasPendingQuestionUI:false);XCTAssertEqual(r?.transcript,s.transcript);XCTAssertEqual(p.state.withLock{$0.events},["load","select","persisted","excluded","normalize","working","protection","present","visibleCount","index"]);XCTAssertEqual(r?.needsReloadMigrationSave,false)}
    func testLegacyRowsBuildWithMaximumSequencePlusOneAndNormalizedRunState() async throws {var s=session(false);s.lastRunState="running";let p=Probe();_ = try await AgentSessionHydrationService(services:ports(s,p)).prepare(sessionID:s.id,hasPendingQuestionUI:true);XCTAssertEqual(p.state.withLock{$0.next},6);XCTAssertEqual(p.state.withLock{$0.states},[.idle]);XCTAssertEqual(p.state.withLock{$0.flags},[true])}
    func testEmptyLegacyRowsStartAtZero() async throws {var s=session(false);s.items=[];let p=Probe();_ = try await AgentSessionHydrationService(services:ports(s,p)).prepare(sessionID:s.id,hasPendingQuestionUI:false);XCTAssertEqual(p.state.withLock{$0.next},0)}
    func testExcludedTranscriptUsesRebuildAndKeepsExistingSequence() async throws {let s=session(),p=Probe();var x=ports(s,p);x.containsExcludedRows={_,flag in p.state.withLock{$0.flags.append(flag)};return true};let r=try await AgentSessionHydrationService(services:x).prepare(sessionID:s.id,hasPendingQuestionUI:true);XCTAssertTrue(p.state.withLock{$0.events.contains("rebuild")});XCTAssertFalse(p.state.withLock{$0.events.contains("build")});XCTAssertEqual(r?.transcript.nextSequenceIndex,6);XCTAssertEqual(p.state.withLock{$0.flags},[true,true])}
    func testFrozenNormalizationOccursBeforeWorkingItemsAndPresentation() async throws {let s=session();var x=ports(s);x.normalizeFrozenLimits={t in var c=t;c.nextSequenceIndex=44;return c};x.workingItems={t in XCTAssertEqual(t.nextSequenceIndex,44);return []};x.present={t,_,_,_ in XCTAssertEqual(t.nextSequenceIndex,44);return 44};let r=try await AgentSessionHydrationService(services:x).prepare(sessionID:s.id,hasPendingQuestionUI:false);XCTAssertEqual(r?.builtPresentation,44);XCTAssertEqual(r?.needsReloadMigrationSave,true)}
    func testPresentationReceivesHostSelectionAndProtection() async throws {let s=session();var x=ports(s);x.present={t,items,selection,id in XCTAssertEqual(selection,"model");XCTAssertEqual(id,t.turns[0].id);XCTAssertEqual(items.count,1);return 1};let r=try await AgentSessionHydrationService(services:x).prepare(sessionID:s.id,hasPendingQuestionUI:false);XCTAssertEqual(r?.normalizedSelection,"model")}
    func testStoredRecencyWinsAndDoesNotEvaluateFallbacks() async throws {let s=session(),p=Probe();let r=try await AgentSessionHydrationService(services:ports(s,p)).prepare(sessionID:s.id,hasPendingQuestionUI:false);XCTAssertEqual(r?.lastUserMessageAt,s.lastUserMessageAt);XCTAssertFalse(p.state.withLock{$0.events.contains("transcriptDate") || $0.events.contains("itemDate")})}
    func testTranscriptRecencyPrecedesItemRecency() async throws {var s=session();s.lastUserMessageAt=nil;let p=Probe(),r=try await AgentSessionHydrationService(services:ports(s,p)).prepare(sessionID:s.id,hasPendingQuestionUI:false);XCTAssertEqual(r?.lastUserMessageAt,Date(timeIntervalSince1970:20));XCTAssertFalse(p.state.withLock{$0.events.contains("itemDate")})}
    func testItemRecencyUsedOnlyWhenStoredAndTranscriptRecencyAreAbsent() async throws {var s=session();s.lastUserMessageAt=nil;var x=ports(s);x.transcriptRecency={_ in nil};let r=try await AgentSessionHydrationService(services:x).prepare(sessionID:s.id,hasPendingQuestionUI:false);XCTAssertEqual(r?.lastUserMessageAt,Date(timeIntervalSince1970:30))}
    func testAbsentRecencyStaysNilAndRequestsMigration() async throws {var s=session();s.lastUserMessageAt=nil;var x=ports(s);x.transcriptRecency={_ in nil};x.itemRecency={_ in nil};let r=try await AgentSessionHydrationService(services:x).prepare(sessionID:s.id,hasPendingQuestionUI:false);XCTAssertNil(r?.lastUserMessageAt);XCTAssertEqual(r?.needsReloadMigrationSave,true)}
    func testMissingItemCountRequestsMigrationWithoutChangingSession() async throws {var s=session();s.itemCount=nil;let r=try await AgentSessionHydrationService(services:ports(s)).prepare(sessionID:s.id,hasPendingQuestionUI:false);XCTAssertEqual(r?.needsReloadMigrationSave,true);XCTAssertNil(r?.persistedSession.itemCount)}
    func testEmptyTranscriptUsesCanonicalItemsCountInsteadOfPresentationCount() async throws {var s=session();s.transcript = .empty;var x=ports(s);let stored=s.items[0];let item=AgentChatItem(id:stored.id,timestamp:stored.timestamp,kind:stored.kind,text:stored.text,sequenceIndex:stored.sequenceIndex);x.workingItems={_ in [item,item]};x.visibleCount={_ in XCTFail("empty transcript");return 10};let r=try await AgentSessionHydrationService(services:x).prepare(sessionID:s.id,hasPendingQuestionUI:false);XCTAssertEqual(r?.restoredIndexEntry.count,2)}
    func testNonemptyTranscriptUsesPresentationCount() async throws {let s=session(),r=try await AgentSessionHydrationService(services:ports(s)).prepare(sessionID:s.id,hasPendingQuestionUI:false);XCTAssertEqual(r?.restoredIndexEntry.count,99)}
    func testRequestedIdentityAndProviderIdentifiersArePreservedIndependently() async throws {let s=session(),requested=UUID(),r=try await AgentSessionHydrationService(services:ports(s)).prepare(sessionID:requested,hasPendingQuestionUI:false);XCTAssertEqual(r?.sessionID,requested);XCTAssertEqual(r?.persistedSession.id,s.id);XCTAssertEqual(r?.persistedSession.providerSessionID,"external-provider-id")}
    func testEveryActiveRunStateNormalizesToIdle() async throws {for state in [AgentSessionRunState.running,.waitingForUser,.waitingForQuestion,.waitingForApproval] {var s=session();s.lastRunState=state.rawValue;let r=try await AgentSessionHydrationService(services:ports(s)).prepare(sessionID:s.id,hasPendingQuestionUI:false);XCTAssertEqual(r?.normalizedRunState,.idle);XCTAssertEqual(r?.persistedSession.lastRunState,state.rawValue)}}
    func testTerminalRunStatesRemainUnchangedAndUnknownDefaultsIdle() async throws {for state in [AgentSessionRunState.idle,.completed,.cancelled,.failed] {var s=session();s.lastRunState=state.rawValue;let r=try await AgentSessionHydrationService(services:ports(s)).prepare(sessionID:s.id,hasPendingQuestionUI:false);XCTAssertEqual(r?.normalizedRunState,state)};var s=session();s.lastRunState="future-state";let r=try await AgentSessionHydrationService(services:ports(s)).prepare(sessionID:s.id,hasPendingQuestionUI:false);XCTAssertEqual(r?.normalizedRunState,.idle);XCTAssertEqual(r?.persistedSession.lastRunState,"future-state")}
    func testCancellationBeforeLoadDoesNotCallLoader() async {let s=session(),p=Probe();let task=Task {withUnsafeCurrentTask{$0?.cancel()};return try await AgentSessionHydrationService(services:ports(s,p)).prepare(sessionID:s.id,hasPendingQuestionUI:false)};do {_ = try await task.value;XCTFail("cancelled")}catch{XCTAssertTrue(error is CancellationError)};XCTAssertTrue(p.state.withLock{$0.events.isEmpty})}
    func testCancellationAfterLoadSkipsPresentationAndPublication() async {let s=session(),p=Probe();var x=ports(s,p);x.load={_ in withUnsafeCurrentTask{$0?.cancel()};return s};let configured=x;let task=Task {try await AgentSessionHydrationService(services:configured).prepare(sessionID:s.id,hasPendingQuestionUI:false)};do {_ = try await task.value;XCTFail("cancelled")}catch{XCTAssertTrue(error is CancellationError)};XCTAssertFalse(p.state.withLock{$0.events.contains("present") || $0.events.contains("index")});XCTAssertEqual(p.state.withLock{$0.observations.last?.outcome},.cancelled)}
    func testCancellationDuringPresentationSkipsIndexAndResult() async {let s=session(),p=Probe();var x=ports(s,p);x.present={_,_,_,_ in withUnsafeCurrentTask{$0?.cancel()};return 0};let configured=x;let task=Task {try await AgentSessionHydrationService(services:configured).prepare(sessionID:s.id,hasPendingQuestionUI:false)};do {_ = try await task.value;XCTFail("cancelled")}catch{XCTAssertTrue(error is CancellationError)};XCTAssertFalse(p.state.withLock{$0.events.contains("index")})}
    func testLoaderErrorsPropagateAndAreObservedOnce() async {struct Failure:Error{};let p=Probe();var x=ports(nil,p);x.load={_ in throw Failure()};do {_ = try await AgentSessionHydrationService(services:x).prepare(sessionID:UUID(),hasPendingQuestionUI:false);XCTFail("error")}catch{XCTAssertTrue(error is Failure)};XCTAssertEqual(p.state.withLock{$0.observations.count},1);XCTAssertEqual(p.state.withLock{$0.observations[0].outcome},.error)}
    func testCallerActorIsInheritedAcrossLoaderAwait() async throws {actor Owner {var count=0;func run() async throws->Int {let s=session();var x=ports(s);x.load={_ in await Task.yield();return s};let owner=self;x.present={_,_,_,_ in owner.preconditionIsolated();return 0};_ = try await AgentSessionHydrationService(services:x).prepare(sessionID:s.id,hasPendingQuestionUI:false);count+=1;return count}};let result=try await Owner().run();XCTAssertEqual(result,1)}
    func testDiagnosticsIncludeSuccessCountsAndMigrationFlag() async throws {let s=session(),p=Probe();_ = try await AgentSessionHydrationService(services:ports(s,p)).prepare(sessionID:s.id,hasPendingQuestionUI:false);let d=p.state.withLock{$0.observations[0]};XCTAssertEqual(d.outcome,.payload);XCTAssertEqual(d.canonicalLiveItems,1);XCTAssertEqual(d.turns,1);XCTAssertEqual(d.needsReloadMigrationSave,false);XCTAssertNil(d.totalDurationMS)}
    func testSendablePreparedResultCanCrossActorBoundary() async throws {func accept<T:Sendable>(_ value:T){};let s=session(),r=try await AgentSessionHydrationService(services:ports(s)).prepare(sessionID:s.id,hasPendingQuestionUI:false);accept(r)}
    func testChangedRebuildRequestsMigrationAndPreservesPersistedCopy() async throws {
        let s=session();var x=ports(s);x.containsExcludedRows={_,_ in true};x.rebuild={t,_,_,_ in var copy=t;copy.nextSequenceIndex=77;return copy}
        let r=try await AgentSessionHydrationService(services:x).prepare(sessionID:s.id,hasPendingQuestionUI:false)
        XCTAssertEqual(r?.transcript.nextSequenceIndex,77);XCTAssertEqual(r?.persistedSession.transcript?.nextSequenceIndex,6);XCTAssertEqual(r?.needsReloadMigrationSave,true)
    }
    func testModelNormalizationIsExplicitHostPolicyWithoutChangingRawPreference() async throws {
        let s=session();var x=ports(s);x.select={_ in "host-normalized"};let r=try await AgentSessionHydrationService(services:x).prepare(sessionID:s.id,hasPendingQuestionUI:false)
        XCTAssertEqual(r?.normalizedSelection,"host-normalized");XCTAssertEqual(r?.persistedSession.agentModel,"model")
    }
    func testNilRunStateDefaultsToIdle() async throws {
        var s=session();s.lastRunState=nil;let r=try await AgentSessionHydrationService(services:ports(s)).prepare(sessionID:s.id,hasPendingQuestionUI:false);XCTAssertEqual(r?.normalizedRunState,.idle)
    }
    func testPendingQuestionFalseIsForwardedToCanonicalPolicy() async throws {
        let s=session(),p=Probe();_ = try await AgentSessionHydrationService(services:ports(s,p)).prepare(sessionID:s.id,hasPendingQuestionUI:false);XCTAssertEqual(p.state.withLock{$0.flags},[false])
    }
    func testMissingSessionAfterCancellationRetainsLegacyNilOutcome() async throws {
        let p=Probe();var x=ports(nil,p);x.load={_ in withUnsafeCurrentTask{$0?.cancel()};return nil};let configured=x
        let task=Task {try await AgentSessionHydrationService(services:configured).prepare(sessionID:UUID(),hasPendingQuestionUI:false)};let result=try await task.value
        XCTAssertNil(result);XCTAssertEqual(p.state.withLock{$0.observations.last?.outcome},.missingSession)
    }

}
